    const local = await chrome.storage.local.get(LEGACY_KEY);
    if (local[LEGACY_KEY] != null) return local[LEGACY_KEY];
  } catch {
    /* ignore */
  }
  try {
    return localStorage.getItem(LEGACY_KEY);
  } catch {
    return null;
  }
}

