const SOLID_COLORS = [
  { id: "s1", value: "#000000", label: "Black" },
  { id: "s2", value: "#1e2028", label: "Ink" },
  { id: "s3", value: "#0d1b2a", label: "Midnight" },
  { id: "s4", value: "#0f2218", label: "Forest" },
  { id: "s5", value: "#1a0a2e", label: "Plum" },
];

const GRADIENT_PRESETS = [
  {
    id: "g1",
    value: "linear-gradient(135deg,#1a1a2e,#16213e,#0f3460)",
    label: "Midnight",
  },
  {
    id: "g2",
    value: "linear-gradient(135deg,#0f2027,#203a43,#2c5364)",
    label: "Ocean",
  },
  { id: "g3", value: "linear-gradient(135deg,#667eea,#764ba2)", label: "Dusk" },
  {
    id: "g4",
    value: "linear-gradient(135deg,#11998e,#38ef7d)",
    label: "Emerald",
  },
  {
    id: "g5",
    value: "linear-gradient(135deg,#f7971e,#ffd200)",
    label: "Amber",
  },
  {
    id: "g6",
    value: "linear-gradient(135deg,#f093fb,#f5576c)",
    label: "Bloom",
  },
];

// Default background when the user hasn't chosen one — the bundled aurora photo.
export const DEFAULT_BACKGROUND = {
  type: "photo",
  value: "img/aurora.webp",
};

// Photo-only appearance modifiers (transparency + blur + which color the photo
// fades toward). They apply to image backgrounds only, never colors/gradients.
const PHOTO_BLUR_MAX = 20;
export const DEFAULT_PHOTO_ADJUST = {
  transparency: 0, // % the photo fades toward the fade color (0 = full photo)
  blur: 0, // px of CSS blur() on the photo
  fade: "bw", // "bw" (light → #fff, dark → #000) | "accent" (sampled color)
};

// Only image backgrounds carry the transparency/blur modifiers.
function isPhotoBackground(type) {
  return type === "photo" || type === "custom";
}

function clampNumber(value, min, max, fallback) {
  const n = Number(value);
  if (!Number.isFinite(n)) return fallback;
  return Math.min(max, Math.max(min, n));
}

// Translate the stored photo modifiers into the CSS custom properties the
// wallpaper pseudo-layers read (see meridian.css). For non-photo backgrounds
// the modifiers are neutralized so colors/gradients render untouched. This is
// pure interpolation against already-derived values (the live --accent var and
// the theme's black/white) — it never re-samples the photo's pixels, so it is
// cheap enough to call on every slider tick.
export function applyPhotoAdjustments(bg, adjust) {
  const root = document.documentElement;
  if (!bg || !isPhotoBackground(bg.type)) {
    root.style.setProperty("--photo-opacity", "1");
    root.style.setProperty("--photo-blur", "0px");
    root.style.setProperty("--photo-fade-color", "transparent");
    return;
  }
  const a = { ...DEFAULT_PHOTO_ADJUST, ...(adjust ?? {}) };
  const transparency = clampNumber(a.transparency, 0, 100, 0);
  const blur = clampNumber(a.blur, 0, PHOTO_BLUR_MAX, 0);
  root.style.setProperty("--photo-opacity", String(1 - transparency / 100));
  root.style.setProperty("--photo-blur", `${blur}px`);
  root.style.setProperty(
    "--photo-fade-color",
    a.fade === "bw" ? "var(--photo-fade-bw)" : "var(--accent)",
  );
}

function generateSeeds(count = 12, exclude = new Set()) {
  const seeds = new Set();
  while (seeds.size < count) {
    const s = String(Math.floor(Math.random() * 9000) + 1000);
    if (!exclude.has(s)) seeds.add(s);
  }
  return [...seeds];
}

export function createSettingsPanel(container) {
  let newTabBehavior = "meridian-view";
  let groupByDomain = false;
  let homepageUrl = "";
  let currentTheme = "system";
  let currentBg = DEFAULT_BACKGROUND;
  let customBgUrl = null;
  // The photo grid holds 12 tiles in a 3×4 layout; the first is the custom
  // image tile, so we only need 11 stock photo seeds.
  let photoSeeds = generateSeeds(11);
  let photoAdjust = { ...DEFAULT_PHOTO_ADJUST };

  const panel = document.createElement("div");

  // Settings are grouped into labeled sections; each control group is
  // appended to one of these rather than straight onto the panel.
  function makeSection(titleText) {
    const section = document.createElement("div");
    section.className = "settings-section";
    const heading = document.createElement("h3");
    heading.className = "settings-section-title";
    heading.textContent = titleText;
    section.appendChild(heading);
    return section;
  }

  const appearanceSection = makeSection("Appearance");
  const searchSection = makeSection("Search");
  const tabsSection = makeSection("Tabs");

  // --- Privacy & Data disclosure ---
  // Native details/summary keeps the disclosure keyboard-accessible while
  // allowing it to remain collapsed at the bottom of Settings by default.
  const privacySection = document.createElement("details");
  privacySection.className = "settings-section settings-privacy-section";

  const privacySummary = document.createElement("summary");
  privacySummary.className = "settings-privacy-summary";
  privacySummary.textContent = "Privacy & Data";
  privacySection.appendChild(privacySummary);

  const privacyGroup = document.createElement("div");
  privacyGroup.className = "settings-group settings-privacy-group";

  const privacyIntro = document.createElement("p");
  privacyIntro.className = "settings-privacy-text";
  privacyIntro.textContent =
    "Meridian automatically captures a screenshot of your active tab to " +
    "show live thumbnails, and after an open tab finishes loading, reads " +
    "that page's meta description and heading (H1/H2) text to power local " +
    "open-tab search. Both happen automatically, without a separate " +
    "prompt, as part of the Tabs and Search features.";

  const privacyStorage = document.createElement("p");
  privacyStorage.className = "settings-privacy-text";
  privacyStorage.textContent =
    "This data is stored locally in your Chrome profile. Meridian has no " +
    "server and never uploads it. Search options controls which " +
    "sources are searchable, and Thumbnails lets you " +
    "regenerate them on demand.";

  const privacyOptional = document.createElement("p");
  privacyOptional.className = "settings-privacy-text";
  privacyOptional.textContent =
    "Bookmark and history access is never automatic — Meridian only asks " +
    "Chrome for that permission when you turn on Bookmarks or History " +
    "under Search options.";

  const privacyLink = document.createElement("a");
  privacyLink.className = "settings-privacy-link";
  privacyLink.href = PRIVACY_POLICY_URL;
  privacyLink.target = "_blank";
  privacyLink.rel = "noopener noreferrer";
  privacyLink.textContent = "Read the full privacy policy";

  privacyGroup.append(
    privacyIntro,
    privacyStorage,
    privacyOptional,
    privacyLink,
  );
  privacySection.appendChild(privacyGroup);

  // --- New tab behavior ---
  const newTabGroup = document.createElement("div");
  newTabGroup.className = "settings-group";

  const newTabLabel = document.createElement("span");
  newTabLabel.className = "settings-label";
  newTabLabel.textContent = "New Tab Behavior";
  newTabGroup.appendChild(newTabLabel);

  // Card grid (radiogroup): each option shows a diagram of what happens,
  // replacing the native <select>. Full radio semantics + arrow-key nav.
  const newTabRow = document.createElement("div");
  newTabRow.className = "settings-behavior-grid";
  newTabRow.setAttribute("role", "radiogroup");
  newTabRow.setAttribute("aria-label", "New Tab Behavior");
  newTabGroup.appendChild(newTabRow);

  function renderNewTabCards() {
    newTabRow.innerHTML = "";
    NEW_TAB_OPTIONS.forEach((o, i) => {
      const selected = o.id === newTabBehavior;
      const card = document.createElement("button");
      card.type = "button";
      card.className =
        "settings-behavior-card" + (selected ? " selected" : "");
      card.setAttribute("role", "radio");
      card.setAttribute("aria-checked", selected ? "true" : "false");
      card.tabIndex = selected ? 0 : -1;

      const fig = document.createElement("span");
      fig.className = "settings-behavior-diagram";
      fig.setAttribute("aria-hidden", "true");
      fig.innerHTML = NEW_TAB_DIAGRAMS[o.id] ?? "";
      card.appendChild(fig);

      const cap = document.createElement("span");
      cap.className = "settings-behavior-caption";
      cap.textContent = o.label;
      card.appendChild(cap);

      card.addEventListener("click", () => selectNewTab(o.id));
      card.addEventListener("keydown", (e) => {
        let ni = -1;
        if (e.key === "ArrowRight" || e.key === "ArrowDown")
          ni = (i + 1) % NEW_TAB_OPTIONS.length;
        else if (e.key === "ArrowLeft" || e.key === "ArrowUp")
          ni = (i - 1 + NEW_TAB_OPTIONS.length) % NEW_TAB_OPTIONS.length;
        if (ni >= 0) {
          e.preventDefault();
          selectNewTab(NEW_TAB_OPTIONS[ni].id, true);
        }
      });

      newTabRow.appendChild(card);
    });
  }

  function selectNewTab(id, focus) {
    newTabBehavior = id;
    chrome.storage.sync.set({ newTabBehavior: id });
    syncNewTab();
    if (focus) {
      const el = newTabRow.querySelector(".settings-behavior-card.selected");
      if (el) el.focus();
    }
  }

  // Only the "open a specific page" option needs a URL field; it appears
  // beneath the grid when that option is selected.
  const homepageField = document.createElement("div");
  homepageField.className = "settings-homepage-field";

  const homepageInput = document.createElement("input");
  homepageInput.type = "url";
  homepageInput.className = "settings-homepage-input";
  homepageInput.placeholder = "https://example.com";
  homepageInput.setAttribute(
    "aria-describedby",
    "settings-homepage-feedback",
  );

  const homepageFeedback = document.createElement("p");
  homepageFeedback.id = "settings-homepage-feedback";
  homepageFeedback.className = "settings-homepage-feedback";
  homepageFeedback.setAttribute("role", "alert");

  function setHomepageError(message) {
    homepageInput.setCustomValidity(message);
    homepageInput.setAttribute("aria-invalid", String(!!message));
    homepageFeedback.textContent = message;
  }

  homepageInput.addEventListener("change", () => {
    const normalized = normalizeHomepageUrl(homepageInput.value);
    if (normalized == null) {
      setHomepageError("Enter a complete http:// or https:// URL.");
      return;
    }

    setHomepageError("");
    homepageUrl = normalized;
    homepageInput.value = normalized;
    chrome.storage.sync.set({ homepageUrl });
  });
  homepageInput.addEventListener("keydown", (e) => {
    if (e.key === "Enter") homepageInput.blur();
  });
  homepageField.append(homepageInput, homepageFeedback);
  newTabGroup.appendChild(homepageField);

  function syncNewTab() {
    renderNewTabCards();
    homepageInput.value = homepageUrl;
    homepageField.classList.toggle(
      "hidden",
      newTabBehavior !== "open-homepage",
    );
  }

  tabsSection.appendChild(newTabGroup);

  // --- Group by domain ---
  const domainGroup = document.createElement("div");
  domainGroup.className = "settings-group";

  const domainLabel = document.createElement("span");
  domainLabel.className = "settings-label";
  domainLabel.textContent = "Tab Organization";
  domainGroup.appendChild(domainLabel);

  const toggleRow = document.createElement("label");
  toggleRow.className = "settings-toggle-row";

  const toggleCheckbox = document.createElement("input");
  toggleCheckbox.type = "checkbox";
  toggleCheckbox.className = "settings-toggle";
  toggleCheckbox.setAttribute("aria-label", "Group unsorted tabs by domain");

  const toggleLabel = document.createElement("span");
  toggleLabel.textContent = "Group unsorted tabs by domain";

  toggleCheckbox.addEventListener("change", () => {
    groupByDomain = toggleCheckbox.checked;
    chrome.storage.sync.set({ groupByDomain });
    window.dispatchEvent(new CustomEvent("settings-changed"));
  });

  toggleRow.appendChild(toggleCheckbox);
  toggleRow.appendChild(toggleLabel);
  domainGroup.appendChild(toggleRow);
  tabsSection.appendChild(domainGroup);

  // --- Search options ---
  const localSearchGroup = document.createElement("div");
  localSearchGroup.className = "settings-group";

  const localSearchLabel = document.createElement("span");
  localSearchLabel.className = "settings-label";
  localSearchLabel.textContent = "Search options";
  localSearchGroup.appendChild(localSearchLabel);

  let localSearch = { ...DEFAULT_LOCAL_SEARCH };

  const localSearchSources = [
    { key: "tabs", label: "Open Tabs" },
    { key: "bookmarks", label: "Bookmarks", optional: true },
    { key: "history", label: "History", optional: true },
  ];

  const localSearchCheckboxes = {};
  const permissionStatus = document.createElement("p");
  permissionStatus.className = "settings-permission-status";
  permissionStatus.setAttribute("aria-live", "polite");

  for (const source of localSearchSources) {
    const row = document.createElement("label");
    row.className = "settings-toggle-row";

    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.className = "settings-toggle";
    checkbox.setAttribute("aria-label", source.label);
    checkbox.checked = localSearch[source.key];

    const label = document.createElement("span");
    label.textContent = source.label;

    checkbox.addEventListener("change", async () => {
      const requested = checkbox.checked;
      checkbox.disabled = true;
      try {
        const result = await setLocalSearchSourceEnabled(
          source.key,
          requested,
        );
        localSearch[source.key] = result.enabled;
        checkbox.checked = result.enabled;
        // Only the denial case needs explaining — a plain enable/disable is
        // already reflected by the checkbox itself.
        permissionStatus.textContent =
          source.optional && result.denied
            ? `${source.label} permission was not granted. This source remains off.`
            : "";
        window.dispatchEvent(new CustomEvent("settings-changed"));
      } catch {
        checkbox.checked = localSearch[source.key];
        permissionStatus.textContent =
          `Could not update ${source.label.toLowerCase()} access.`;
      } finally {
        checkbox.disabled = false;
      }
    });

    row.appendChild(checkbox);
    row.appendChild(label);
    localSearchGroup.appendChild(row);
    localSearchCheckboxes[source.key] = checkbox;
  }
  localSearchGroup.appendChild(permissionStatus);

  async function syncLocalSearchCheckboxes(savedSources) {
    const enabled = await getEnabledLocalSearchSources(savedSources);
    localSearch = { ...localSearch, ...enabled };
    for (const [key, checkbox] of Object.entries(localSearchCheckboxes)) {
      checkbox.checked = enabled[key];
    }
  }

  chrome.storage.onChanged.addListener((changes, area) => {
    if (area !== "sync" || !changes.localSearch) return;
    syncLocalSearchCheckboxes(changes.localSearch.newValue);
  });

  // (Appended below, after Search Engine, so the engine picker sits on top.)

  // --- Search Engine ---
  let searchProvider = PROVIDERS[0].id;

  const searchEngineGroup = document.createElement("div");
  searchEngineGroup.className = "settings-group";

  const searchEngineLabel = document.createElement("span");
  searchEngineLabel.className = "settings-label";
  searchEngineLabel.textContent = "Search Engine";
  searchEngineGroup.appendChild(searchEngineLabel);

  // Provider card grid (radiogroup): each card shows the provider's favicon +
  // name — the native <select> couldn't render provider marks.
  const searchEngineRow = document.createElement("div");
  searchEngineRow.className = "settings-provider-grid";
  searchEngineRow.setAttribute("role", "radiogroup");
  searchEngineRow.setAttribute("aria-label", "Search Engine");
  searchEngineGroup.appendChild(searchEngineRow);

  function renderProviderCards() {
    searchEngineRow.innerHTML = "";
    PROVIDERS.forEach((p, i) => {
      const selected = p.id === searchProvider;
      const card = document.createElement("button");
      card.type = "button";
      card.className =
        "settings-provider-card" + (selected ? " selected" : "");
      card.setAttribute("role", "radio");
      card.setAttribute("aria-checked", selected ? "true" : "false");
      card.tabIndex = selected ? 0 : -1;

      const icon = document.createElement("img");
      icon.className = "settings-provider-icon";
      icon.src = p.favicon;
      icon.alt = "";
      icon.setAttribute("aria-hidden", "true");
      icon.loading = "lazy";
      // If a favicon fails to load, hide the broken-image glyph gracefully.
      icon.addEventListener("error", () => {
        icon.classList.add("load-failed");
      });
      card.appendChild(icon);

      const cap = document.createElement("span");
      cap.className = "settings-provider-name";
      cap.textContent = p.name;
      card.appendChild(cap);

      card.addEventListener("click", () => selectProvider(p.id));
      card.addEventListener("keydown", (e) => {
        let ni = -1;
        if (e.key === "ArrowRight" || e.key === "ArrowDown")
          ni = (i + 1) % PROVIDERS.length;
        else if (e.key === "ArrowLeft" || e.key === "ArrowUp")
          ni = (i - 1 + PROVIDERS.length) % PROVIDERS.length;
        if (ni >= 0) {
          e.preventDefault();
          selectProvider(PROVIDERS[ni].id, true);
        }
      });

      searchEngineRow.appendChild(card);
    });
  }

  function selectProvider(id, focus) {
    searchProvider = id;
    chrome.storage.sync.set({ searchProvider: id });
    renderProviderCards();
    if (focus) {
      const el = searchEngineRow.querySelector(
        ".settings-provider-card.selected"
      );
      if (el) el.focus();
    }
  }

  // Search Engine on top, then Search options beneath it.
  searchSection.append(searchEngineGroup, localSearchGroup);

  // --- Theme ---
  const themeGroup = document.createElement("div");
  themeGroup.className = "settings-group";

  const themeLabel = document.createElement("span");
  themeLabel.className = "settings-label";
  themeLabel.textContent = "Theme";
  themeGroup.appendChild(themeLabel);

  const themeRow = document.createElement("div");
  themeRow.className = "settings-theme-row";

  const THEMES = [
    { id: "light", label: "Light" },
    { id: "dark", label: "Dark" },
    { id: "system", label: "System" },
  ];

  function renderThemeButtons() {
    themeRow
      .querySelectorAll(".settings-theme-btn")
      .forEach((el) => el.remove());
    for (const t of THEMES) {
      const btn = document.createElement("button");
      btn.className =
        "settings-theme-btn" + (t.id === currentTheme ? " selected" : "");

      const icon = document.createElement("span");
      icon.className = "settings-theme-icon";
      icon.setAttribute("aria-hidden", "true");
      icon.innerHTML = THEME_ICONS[t.id] ?? "";
      btn.appendChild(icon);

      const label = document.createElement("span");
      label.textContent = t.label;
      btn.appendChild(label);

      btn.addEventListener("click", () => {
        currentTheme = t.id;
        chrome.storage.sync.set({ theme: t.id });
        applyTheme(t.id);
        renderThemeButtons();
      });
      themeRow.appendChild(btn);
    }
  }

  themeGroup.appendChild(themeRow);
  appearanceSection.appendChild(themeGroup);

  // --- Background ---
  const bgGroup = document.createElement("div");
  bgGroup.className = "settings-group";

  const bgLabel = document.createElement("span");
  bgLabel.className = "settings-label";
  bgLabel.textContent = "Background";
  bgGroup.appendChild(bgLabel);

  function isSelected(type, value) {
    return currentBg.type === type && currentBg.value === value;
  }

  function selectBg(type, value) {
    currentBg = { type, value };
    chrome.storage.sync.set({ background: currentBg });
    applyBackground(currentBg, customBgUrl);
    // Accent (canvas pixel-sampling) runs once here, on the photo change — not
    // on slider ticks. The modifiers below only reuse the cached --accent.
    applyAccentFromBackground(currentBg, customBgUrl);
    applyPhotoAdjustments(currentBg, photoAdjust);
    renderBgSection();
  }

  // Live-preview the modifiers without persisting (cheap CSS-var writes only).
  function previewPhotoAdjust() {
    applyPhotoAdjustments(currentBg, photoAdjust);
  }

  // Persist on gesture end (slider release / toggle), not on every tick.
  function persistPhotoAdjust() {
    chrome.storage.sync.set({ photoAdjust: { ...photoAdjust } });
  }

  // Labeled range control with a live numeric readout.
  function makeSlider(opts) {
    const field = document.createElement("div");
    field.className = "settings-slider-field";

    const head = document.createElement("div");
    head.className = "settings-slider-head";

    const name = document.createElement("span");
    name.className = "settings-slider-label";
    name.textContent = opts.label;

    const readout = document.createElement("span");
    readout.className = "settings-slider-value";
    readout.textContent = opts.format(opts.value);

    head.append(name, readout);

    const input = document.createElement("input");
    input.type = "range";
    input.className = "settings-slider";
    input.min = String(opts.min);
    input.max = String(opts.max);
    input.step = String(opts.step);
    input.value = String(opts.value);
    input.setAttribute("aria-label", opts.label);
    input.addEventListener("input", () => {
      const v = Number(input.value);
      readout.textContent = opts.format(v);
      opts.onInput(v);
    });
    input.addEventListener("change", () => opts.onChange());

    field.append(head, input);
    return field;
  }

  // The nested block of photo-only modifiers. Rebuilt each render from the
  // current photoAdjust state, so it always reflects the persisted values.
  function buildPhotoAdjust() {
    const wrap = document.createElement("div");
    wrap.className = "settings-bg-photo-adjust";

    wrap.appendChild(
      makeSlider({
        label: "Transparency",
        min: 0,
        max: 100,
        step: 1,
        value: photoAdjust.transparency,
        format: (v) => `${v}%`,
        onInput: (v) => {
          photoAdjust.transparency = v;
          previewPhotoAdjust();
        },
        onChange: persistPhotoAdjust,
      }),
    );

    wrap.appendChild(
      makeSlider({
        label: "Blur",
        min: 0,
        max: PHOTO_BLUR_MAX,
        step: 1,
        value: photoAdjust.blur,
        format: (v) => `${v}px`,
        onInput: (v) => {
          photoAdjust.blur = v;
          previewPhotoAdjust();
        },
        onChange: persistPhotoAdjust,
      }),
    );

    // Default fade is black/white; check this box to fade toward the
    // sampled accent color instead.
    const toggleRow = document.createElement("label");
    toggleRow.className = "settings-toggle-row";

    const toggle = document.createElement("input");
    toggle.type = "checkbox";
    toggle.className = "settings-toggle";
    toggle.checked = photoAdjust.fade === "accent";
    toggle.setAttribute(
      "aria-label",
      "Fade to the sampled accent color instead of black or white",
    );

    const toggleText = document.createElement("span");
    toggleText.textContent = "Fade to accent color";

    toggle.addEventListener("change", () => {
      photoAdjust.fade = toggle.checked ? "accent" : "bw";
      previewPhotoAdjust();
      persistPhotoAdjust();
    });

    toggleRow.append(toggle, toggleText);
    wrap.appendChild(toggleRow);

    return wrap;
  }

  function makeSwatch(opts) {
    const btn = document.createElement("button");
    btn.className =
      "settings-bg-swatch" +
      (opts.isNone ? " settings-bg-swatch--none" : "") +
      (opts.selected ? " selected" : "");
    if (opts.background) {
      btn.style.setProperty("--swatch-background", opts.background);
    }
    if (opts.label) btn.setAttribute("aria-label", opts.label);
    if (opts.label) btn.title = opts.label;
    if (opts.text) btn.textContent = opts.text;
    if (opts.imgSrc) {
      const img = document.createElement("img");
      img.src = opts.imgSrc;
      img.alt = "";
      img.loading = "lazy";
      img.onerror = () => {
        btn.classList.add("load-failed");
      };
      btn.appendChild(img);
    }
    btn.addEventListener("click", opts.onClick);
    return btn;
  }

  function renderBgSection() {
    bgGroup
      .querySelectorAll(
        ".settings-bg-sublabel-row, .settings-bg-combined-grid, .settings-bg-photo-grid, .settings-bg-photo-adjust, .settings-bg-upload-btn, .settings-bg-file-input",
      )
      .forEach((el) => el.remove());

    // ── Row label: Colors & Gradients ──
    const colorGradRow = document.createElement("div");
    colorGradRow.className = "settings-bg-sublabel-row";
    const colorGradLabel = document.createElement("span");
    colorGradLabel.className = "settings-bg-sublabel";
    colorGradLabel.textContent = "Colors & Gradients";
    colorGradRow.appendChild(colorGradLabel);
    bgGroup.appendChild(colorGradRow);

    // ── Combined 6-column grid: [None, 5 solids] + [6 gradients] ──
    const combinedGrid = document.createElement("div");
    combinedGrid.className = "settings-bg-combined-grid";

    // None
    combinedGrid.appendChild(
      makeSwatch({
        isNone: true,
        selected: currentBg.type === "none",
        label: "No background",
        onClick: () => selectBg("none", ""),
      }),
    );

    // Solid colors
    for (const c of SOLID_COLORS) {
      combinedGrid.appendChild(
        makeSwatch({
          selected: isSelected("solid", c.value),
          background: c.value,
          label: c.label,
          onClick: () => selectBg("solid", c.value),
        }),
      );
    }

    // Gradients
    for (const g of GRADIENT_PRESETS) {
      combinedGrid.appendChild(
        makeSwatch({
          selected: isSelected("gradient", g.value),
          background: g.value,
          label: g.label,
          onClick: () => selectBg("gradient", g.value),
        }),
      );
    }

    bgGroup.appendChild(combinedGrid);

    // ── Row label: Photos + Refresh ──
    const photoRow = document.createElement("div");
    photoRow.className = "settings-bg-sublabel-row";

    const photoLabel = document.createElement("span");
    photoLabel.className = "settings-bg-sublabel";
    photoLabel.textContent = "Photos";

    const refreshBtn = document.createElement("button");
    refreshBtn.className = "settings-bg-refresh";
    refreshBtn.textContent = "↻ Refresh";
    refreshBtn.addEventListener("click", () => {
      photoSeeds = generateSeeds(11, new Set(photoSeeds));
      renderBgSection();
    });

    photoRow.appendChild(photoLabel);
    photoRow.appendChild(refreshBtn);
    bgGroup.appendChild(photoRow);

    // ── Photo grid: 12 tiles in a 3×4 layout. The first tile is the custom
    // image dropzone/add button (or the thumbnail of an uploaded image); the
    // remaining 11 are stock photos. ──
    const photoGrid = document.createElement("div");
    photoGrid.className = "settings-bg-photo-grid";

    // Hidden native file picker, triggered by the custom tile's add button.
    const fileInput = document.createElement("input");
    fileInput.type = "file";
    fileInput.accept = "image/*";
    fileInput.className = "settings-bg-file-input";

    // The custom tile: same footprint as a photo swatch. It is either the
    // "add" affordance (blank --bg tile + plus) or, once an image is stored,
    // that image's thumbnail with a hover-revealed remove control.
    const customTile = document.createElement("div");
    customTile.className =
      "settings-bg-swatch settings-bg-custom" +
      (currentBg.type === "custom" ? " selected" : "");

    async function processCustomImage(file) {
      if (!file) return;
      customTile.classList.remove("drag-over", "upload-error");
      if (!file.type.startsWith("image/")) {
        customTile.classList.add("upload-error");
        customTile.title = "Please choose an image file";
        return;
      }
      customTile.classList.add("processing");
      try {
        await saveCustomBackground(file);
        customBgUrl = await getCustomBackgroundUrl();
        selectBg("custom", ""); // re-renders the section → tile shows the thumb
      } catch {
        customTile.classList.remove("processing");
        customTile.classList.add("upload-error");
        customTile.title = "Could not save image — try another file";
      } finally {
        fileInput.value = "";
      }
    }

    async function removeCustomImage() {
      await clearCustomBackground();
      customBgUrl = null;
      // "Start over": if the removed image was the active background, fall back
      // to the default; otherwise just refresh the tile back to its add state.
      if (currentBg.type === "custom") {
        selectBg(DEFAULT_BACKGROUND.type, DEFAULT_BACKGROUND.value);
      } else {
        renderBgSection();
      }
    }

    if (customBgUrl) {
      // ── Filled state: thumbnail + hover-revealed remove (rotated plus). ──
      customTile.classList.add("settings-bg-custom--filled");
      customTile.setAttribute("role", "button");
      customTile.tabIndex = 0;
      customTile.setAttribute("aria-label", "Use custom image background");
      customTile.title = "Custom image";

      const thumb = document.createElement("img");
      thumb.src = customBgUrl;
      thumb.alt = "";
      customTile.appendChild(thumb);

      const selectCustom = () => selectBg("custom", "");
      customTile.addEventListener("click", selectCustom);
      customTile.addEventListener("keydown", (event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          selectCustom();
        }
      });

      const removeBtn = document.createElement("button");
      removeBtn.type = "button";
      removeBtn.className = "settings-bg-custom-remove";
      removeBtn.textContent = "+"; // rotated 45° into an "X" via CSS
      removeBtn.setAttribute("aria-label", "Remove custom image");
      removeBtn.title = "Remove custom image";
      removeBtn.addEventListener("click", (event) => {
        event.stopPropagation();
        removeCustomImage();
      });
      customTile.appendChild(removeBtn);
    } else {
      // ── Empty state: blank --bg tile + plus; add button and drop target. ──
      customTile.classList.add("settings-bg-custom--empty");

      const addBtn = document.createElement("button");
      addBtn.type = "button";
      addBtn.className = "settings-bg-custom-add";
      addBtn.textContent = "+"; // same glyph as the new-tab buttons
      addBtn.setAttribute("aria-label", "Add a custom image background");
      addBtn.title = "Add custom image";
      addBtn.addEventListener("click", () => fileInput.click());
      customTile.appendChild(addBtn);

      let dragDepth = 0;
      customTile.addEventListener("dragenter", (event) => {
        event.preventDefault();
        dragDepth += 1;
        customTile.classList.add("drag-over");
      });
      customTile.addEventListener("dragover", (event) => {
        event.preventDefault();
        event.dataTransfer.dropEffect = "copy";
        customTile.classList.add("drag-over");
      });
      customTile.addEventListener("dragleave", (event) => {
        event.preventDefault();
        dragDepth = Math.max(0, dragDepth - 1);
        if (dragDepth === 0) customTile.classList.remove("drag-over");
      });
      customTile.addEventListener("drop", (event) => {
        event.preventDefault();
        dragDepth = 0;
        customTile.classList.remove("drag-over");
        processCustomImage(event.dataTransfer.files?.[0]);
      });
    }

    fileInput.addEventListener("change", () =>
      processCustomImage(fileInput.files?.[0]),
    );

    photoGrid.appendChild(fileInput);
    photoGrid.appendChild(customTile);

    for (const seed of photoSeeds) {
      const fullUrl = `https://picsum.photos/seed/${seed}/1920/1080`;
      const thumbUrl = `https://picsum.photos/seed/${seed}/200/125`;
      photoGrid.appendChild(
        makeSwatch({
          selected: isSelected("photo", fullUrl),
          label: `Photo ${seed}`,
          imgSrc: thumbUrl,
          onClick: () => selectBg("photo", fullUrl),
        }),
      );
    }

    bgGroup.appendChild(photoGrid);

    // ── Photo-only modifiers (transparency + blur), at the bottom of the
    // Background section. Shown only while a photo/custom background is
    // active; colors & gradients never carry these controls.
    if (isPhotoBackground(currentBg.type)) {
      bgGroup.appendChild(buildPhotoAdjust());
    }
  }

  appearanceSection.appendChild(bgGroup);

  // --- Refresh thumbnails (a group under Tabs, at the bottom of the panel) ---
  const refreshGroup = document.createElement("div");
  refreshGroup.className = "settings-group";

  const refreshLabel = document.createElement("span");
  refreshLabel.className = "settings-label";
  refreshLabel.textContent = "Thumbnails";
  refreshGroup.appendChild(refreshLabel);

  const refreshBtn = document.createElement("button");
  refreshBtn.className = "settings-action-btn";
  refreshBtn.textContent = "Refresh all thumbnails (this will cycle tabs)";
  refreshBtn.addEventListener("click", async () => {
    refreshBtn.disabled = true;
    refreshBtn.textContent = "Refreshing…";
    await chrome.runtime.sendMessage({ type: "REFRESH_THUMBNAILS" });
    refreshBtn.textContent = "Done";
    setTimeout(() => {
      refreshBtn.disabled = false;
      refreshBtn.textContent = "Refresh all thumbnails (this will cycle tabs)";
    }, 2000);
  });
  refreshGroup.appendChild(refreshBtn);
  tabsSection.appendChild(refreshGroup);

  // --- Emberstone Studio footer ---
  // Two compact, side-by-side calls to action: the studio site (brand mark)
  // and Ko-fi (coffee icon). Static markup only — no chrome.* calls, no click
  // tracking — so it never contacts the network until the user explicitly
  // follows a link. Sits directly above the Privacy & Data disclosure at the
  // very bottom of the panel.
  const emberstoneFooter = document.createElement("div");
  emberstoneFooter.className = "settings-section settings-emberstone";

  // Small muted label (same treatment as .settings-label elsewhere) so this
  // footer has a name like every other section, without promoting it to a
  // full bordered h3 heading — it's a quiet credit, not a config group.
  const emberstoneLabel = document.createElement("span");
  emberstoneLabel.className = "settings-label settings-emberstone-label";
  emberstoneLabel.textContent = "Emberstone Studio";
  emberstoneFooter.appendChild(emberstoneLabel);

  const emberstoneLinks = document.createElement("div");
  emberstoneLinks.className = "settings-emberstone-links";

  // Native <a href target="_blank" rel="noopener noreferrer"> links — the same
  // safe outbound-link pattern as the privacy-policy link above. They open in
  // a new tab, keeping the new-tab/settings context intact, and are keyboard
  // focusable with a visible focus ring from .settings-emberstone-link.
  const emberstoneSiteLink = document.createElement("a");
  emberstoneSiteLink.className = "settings-emberstone-link";
  emberstoneSiteLink.href = "https://emberstone-studio.com";
  emberstoneSiteLink.target = "_blank";
  emberstoneSiteLink.rel = "noopener noreferrer";

  const emberstoneLogo = document.createElement("img");
  emberstoneLogo.className = "settings-emberstone-icon";
  // Root-relative, matching how img/aurora.webp and the icon assets are
  // referenced elsewhere. The SVG is a fixed multi-color mark (not theme
  // adaptive), so one file serves both light and dark.
  emberstoneLogo.src = "img/emberstone.svg";
  // Decorative: the adjacent label already names the studio.
  emberstoneLogo.alt = "";
  emberstoneLogo.width = 22;
  emberstoneLogo.height = 22;
  emberstoneLogo.setAttribute("aria-hidden", "true");
  emberstoneLogo.loading = "lazy";
  // If the asset ever fails to load, hide the broken-image glyph gracefully.
  emberstoneLogo.onerror = () => {
    emberstoneLogo.classList.add("load-failed");
  };

  const emberstoneSiteLabel = document.createElement("span");
  emberstoneSiteLabel.textContent = "See more from Emberstone Studio";

  emberstoneSiteLink.append(emberstoneLogo, emberstoneSiteLabel);

  const emberstoneCoffeeLink = document.createElement("a");
  emberstoneCoffeeLink.className = "settings-emberstone-link";
  emberstoneCoffeeLink.href = "https://ko-fi.com/emberstonestudio";
  emberstoneCoffeeLink.target = "_blank";
  emberstoneCoffeeLink.rel = "noopener noreferrer";

  // Inline (not <img>) so `currentColor` recolors it with the button text,
  // matching the THEME_ICONS pattern above — coffee.svg ships with no fill,
  // so it would otherwise render black in dark mode.
  const emberstoneCoffeeIcon = document.createElement("span");
  emberstoneCoffeeIcon.className = "settings-emberstone-icon";
  emberstoneCoffeeIcon.setAttribute("aria-hidden", "true");
  emberstoneCoffeeIcon.innerHTML =
    '<svg viewBox="0 0 640 640" width="22" height="22" aria-hidden="true"><path fill="currentColor" d="M184 48C170.7 48 160 58.7 160 72C160 110.9 183.4 131.4 199.1 145.1L200.2 146.1C216.5 160.4 224 167.9 224 184C224 197.3 234.7 208 248 208C261.3 208 272 197.3 272 184C272 145.1 248.6 124.6 232.9 110.9L231.8 109.9C215.5 95.7 208 88.1 208 72C208 58.7 197.3 48 184 48zM128 256C110.3 256 96 270.3 96 288L96 480C96 533 139 576 192 576L384 576C425.8 576 461.4 549.3 474.5 512L480 512C550.7 512 608 454.7 608 384C608 313.3 550.7 256 480 256L128 256zM480 448L480 320C515.3 320 544 348.7 544 384C544 419.3 515.3 448 480 448zM320 72C320 58.7 309.3 48 296 48C282.7 48 272 58.7 272 72C272 110.9 295.4 131.4 311.1 145.1L312.2 146.1C328.5 160.4 336 167.9 336 184C336 197.3 346.7 208 360 208C373.3 208 384 197.3 384 184C384 145.1 360.6 124.6 344.9 110.9L343.8 109.9C327.5 95.7 320 88.1 320 72z"/></svg>';

  const emberstoneCoffeeLabel = document.createElement("span");
  emberstoneCoffeeLabel.textContent = "Buy us a coffee";

  emberstoneCoffeeLink.append(emberstoneCoffeeIcon, emberstoneCoffeeLabel);

  emberstoneLinks.append(emberstoneSiteLink, emberstoneCoffeeLink);
  emberstoneFooter.append(emberstoneLinks);

  // Keep the optional Privacy & Data disclosure last so primary settings
  // remain immediately available; the Emberstone credit sits just above it.
  panel.append(
    appearanceSection,
    searchSection,
    tabsSection,
    emberstoneFooter,
    privacySection,
  );

  container.appendChild(panel);

  chrome.storage.sync
    .get([
      "newTabBehavior",
      "groupByDomain",
      "homepageUrl",
      "theme",
      "background",
      "photoAdjust",
      "localSearch",
      "searchProvider",
    ])
    .then((saved) => {
      if (saved.newTabBehavior) newTabBehavior = saved.newTabBehavior;
      groupByDomain = !!saved.groupByDomain;
      homepageUrl = saved.homepageUrl ?? "";
      currentTheme = saved.theme ?? "system";
      currentBg = saved.background ?? DEFAULT_BACKGROUND;
      photoAdjust = { ...DEFAULT_PHOTO_ADJUST, ...(saved.photoAdjust ?? {}) };
      toggleCheckbox.checked = groupByDomain;
      // Resolve the stored custom image up front so its thumbnail shows in the
      // custom tile even when a different background is currently active.
      const background = currentBg;
      const customUrlPromise = getCustomBackgroundUrl();
      if (currentBg.type === "custom") {
        applyAccentFromBackground(background, customUrlPromise);
      }
      customUrlPromise.then((url) => {
        customBgUrl = url;
        if (currentBg === background && currentBg.type === "custom") {
          applyBackground(background, customBgUrl);
        }
        renderBgSection();
      });
      if (saved.localSearch) {
        localSearch = { ...localSearch, ...saved.localSearch };
      }
      syncLocalSearchCheckboxes(saved.localSearch);
      if (
        saved.searchProvider &&
        PROVIDERS.some((p) => p.id === saved.searchProvider)
      ) {
        searchProvider = saved.searchProvider;
      }
      syncNewTab();
      renderThemeButtons();
      renderBgSection();
      renderProviderCards();
    });

  syncNewTab();
  renderThemeButtons();
  renderBgSection();
  renderProviderCards();
}

// ── Auto accent: derive the accent hue from the active background ──
// The accent tracks the background's dominant hue; the theme keeps saturation
// and lightness (see meridian.css), and a contrast guard nudges lightness so
// the accent can never collapse into a same-toned solid background.

function hexToRgb(hex) {
  const m = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(String(hex).trim());
  if (!m) return null;
  let h = m[1];
  if (h.length === 3) h = h.split("").map((c) => c + c).join("");
  const int = parseInt(h, 16);
  return [(int >> 16) & 255, (int >> 8) & 255, int & 255];
}

function rgbToHsl(r, g, b) {
  r /= 255;
  g /= 255;
  b /= 255;
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const l = (max + min) / 2;
  const d = max - min;
  let h = 0;
  let s = 0;
  if (d !== 0) {
    s = d / (1 - Math.abs(2 * l - 1));
    if (max === r) h = ((g - b) / d) % 6;
    else if (max === g) h = (b - r) / d + 2;
    else h = (r - g) / d + 4;
    h = Math.round(h * 60);
    if (h < 0) h += 360;
  }
  return { h, s: Math.round(s * 100), l: Math.round(l * 100) };
}

// Pick the most saturated stop of a gradient/solid — the color that gives
// the background its identity, not the muddy average of all stops.
function dominantHex(str) {
  const hexes = String(str).match(/#[0-9a-f]{6}|#[0-9a-f]{3}/gi);
  if (!hexes || !hexes.length) return null;
  let best = null;
  for (const hx of hexes) {
    const rgb = hexToRgb(hx);
    if (!rgb) continue;
    const hsl = rgbToHsl(...rgb);
    if (!best || hsl.s > best.s) best = hsl;
  }
  return best;
}

// Find an image's dominant *vivid* hue via a saturation-weighted histogram.
// A plain pixel average collapses to gray and throws the real color away.
// Also returns the image's overall luminance (all opaque pixels) so callers
// can decide whether content sitting on it needs light or dark text.
function analyzeImage(url) {
  return new Promise((resolve) => {
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.onload = () => {
      try {
        const size = 48;
        const canvas = document.createElement("canvas");
        canvas.width = size;
        canvas.height = size;
        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0, size, size);
        const { data } = ctx.getImageData(0, 0, size, size);
        const BINS = 24;
        const weight = new Array(BINS).fill(0);
        const sSum = new Array(BINS).fill(0);
        const lSum = new Array(BINS).fill(0);
        const count = new Array(BINS).fill(0);
        let lumSum = 0;
        let lumN = 0;
        for (let i = 0; i < data.length; i += 4) {
          if (data[i + 3] < 125) continue;
          lumSum += relLum(data[i], data[i + 1], data[i + 2]);
          lumN += 1;
          const hsl = rgbToHsl(data[i], data[i + 1], data[i + 2]);
          // Skip grays and near black/white — they carry no hue identity.
          if (hsl.s < 18 || hsl.l < 10 || hsl.l > 92) continue;
          const bin = Math.floor((hsl.h / 360) * BINS) % BINS;
          weight[bin] += hsl.s / 100; // vivid pixels weigh more
          sSum[bin] += hsl.s;
          lSum[bin] += hsl.l;
          count[bin] += 1;
        }
        const lum = lumN ? lumSum / lumN : null;
        let top = -1;
        let topW = 0;
        for (let b = 0; b < BINS; b += 1) {
          if (weight[b] > topW) {
            topW = weight[b];
            top = b;
          }
        }
        if (top < 0) return resolve({ dominant: null, lum }); // no vivid pixels
        resolve({
          dominant: {
            h: Math.round(((top + 0.5) / BINS) * 360),
            s: Math.round(sSum[top] / count[top]),
            l: Math.round(lSum[top] / count[top]),
          },
          lum,
        });
      } catch {
        resolve({ dominant: null, lum: null }); // cross-origin taint, etc.
      }
    };
    img.onerror = () => resolve({ dominant: null, lum: null });
    img.src = url;
  });
}

// Average relative luminance across every hex stop in a string.
function averageLumOfHexes(str) {
  const hexes = String(str).match(/#[0-9a-f]{6}|#[0-9a-f]{3}/gi);
  if (!hexes || !hexes.length) return null;
  let sum = 0;
  let n = 0;
  for (const hx of hexes) {
    const rgb = hexToRgb(hx);
    if (!rgb) continue;
    sum += relLum(...rgb);
    n += 1;
  }
  return n ? sum / n : null;
}

// Returns { dominant, lum } for the active background. `lum` is null for the
// "none" background, which follows the theme's --bg (read live at apply time).
async function analyzeBackground(bg, customDataUrl) {
  if (!bg || bg.type === "none") return { dominant: null, lum: null };
  if (bg.type === "solid") {
    const rgb = hexToRgb(bg.value);
    return {
      dominant: rgb ? rgbToHsl(...rgb) : null,
      lum: rgb ? relLum(...rgb) : null,
    };
  }
  if (bg.type === "gradient") {
    return { dominant: dominantHex(bg.value), lum: averageLumOfHexes(bg.value) };
  }
  if (bg.type === "photo") return analyzeImage(bg.value);
  if (bg.type === "custom") {
    return customDataUrl
      ? analyzeImage(customDataUrl)
      : { dominant: null, lum: null };
  }
  return { dominant: null, lum: null };
}

// ── Color math for the surface-contrast solver ──
function hslToRgb(h, s, l) {
  s /= 100;
  l /= 100;
  const c = (1 - Math.abs(2 * l - 1)) * s;
  const x = c * (1 - Math.abs(((h / 60) % 2) - 1));
  const m = l - c / 2;
  let r = 0;
  let g = 0;
  let b = 0;
  if (h < 60) [r, g, b] = [c, x, 0];
  else if (h < 120) [r, g, b] = [x, c, 0];
  else if (h < 180) [r, g, b] = [0, c, x];
  else if (h < 240) [r, g, b] = [0, x, c];
  else if (h < 300) [r, g, b] = [x, 0, c];
  else [r, g, b] = [c, 0, x];
  return [(r + m) * 255, (g + m) * 255, (b + m) * 255];
}

function relLum(r, g, b) {
  const a = [r, g, b].map((v) => {
    const n = v / 255;
    return n <= 0.03928 ? n / 12.92 : ((n + 0.055) / 1.055) ** 2.4;
  });
  return 0.2126 * a[0] + 0.7152 * a[1] + 0.0722 * a[2];
}

function contrastRatio(l1, l2) {
  const hi = Math.max(l1, l2);
  const lo = Math.min(l1, l2);
  return (hi + 0.05) / (lo + 0.05);
}

// Luminance of the actual --surface the accent renders on (cards, panels).
function surfaceLum() {
  const v = getComputedStyle(document.documentElement)
    .getPropertyValue("--surface")
    .trim();
  const rgb = hexToRgb(v);
  if (rgb) return relLum(...rgb);
  return docIsDark() ? 0.035 : 1;
}

// Derived accents run a touch under full saturation — neon reads cheap.
const ACCENT_SAT = 80;

// Last resolved dominant + background luminance, cached so a theme switch can
// re-run the solver and re-pick on-background text without re-sampling.
let lastDominant = null;
let lastBgLum = null;
let accentGeneration = 0;

function docIsDark() {
  const t = document.documentElement.dataset.theme;
  if (t === "dark") return true;
  if (t === "light") return false;
  return window.matchMedia("(prefers-color-scheme: dark)").matches;
}

function applyDerivedAccent(dominant) {
  const root = document.documentElement;
  // Grayscale / very desaturated → no meaningful hue; use the default.
  if (!dominant || dominant.s < 12) {
    root.style.removeProperty("--accent-hue");
    root.style.removeProperty("--accent-sat");
    root.style.removeProperty("--accent-light");
    return;
  }

  // Solve for a lightness that clears a legible contrast against the SURFACE
  // (where the accent actually lives), searching in the safe direction and
  // staying inside a tasteful band so filled-accent glyphs stay readable too.
  const hue = dominant.h;
  const dark = docIsDark();
  const surf = surfaceLum();
  const target = 3.5;
  const floor = dark ? 48 : 30;
  const ceil = dark ? 70 : 50;
  let l = dark ? 58 : 44;
  const step = dark ? 2 : -2;
  for (let i = 0; i < 40; i += 1) {
    const [r, g, b] = hslToRgb(hue, ACCENT_SAT, l);
    if (contrastRatio(relLum(r, g, b), surf) >= target) break;
    l += step;
    if (l <= floor) {
      l = floor;
      break;
    }
    if (l >= ceil) {
      l = ceil;
      break;
    }
  }

  root.style.setProperty("--accent-hue", String(hue));
  root.style.setProperty("--accent-sat", `${ACCENT_SAT}%`);
  root.style.setProperty("--accent-light", `${l}%`);
}

// Content that sits directly on the background (lane headers) can't rely on the
// theme's text color — the wallpaper may be light or dark regardless of theme.
// Pick light or dark on-background text from the background's own luminance,
// plus a contrasting text-shadow scrim so it survives busy photos.
function applyOnBackground(lum) {
  const root = document.documentElement;
  let L = lum;
  if (L == null) {
    // "none" background follows the theme's --bg — read it live.
    const v = getComputedStyle(root).getPropertyValue("--bg").trim();
    const rgb = hexToRgb(v);
    L = rgb ? relLum(...rgb) : docIsDark() ? 0.02 : 0.9;
  }
  if (L < 0.4) {
    // Dark background → light text.
    root.style.setProperty("--on-bg", "rgba(255, 255, 255, 0.95)");
    root.style.setProperty("--on-bg-muted", "rgba(255, 255, 255, 0.72)");
    root.style.setProperty("--on-bg-shadow", "0 1px 3px rgba(0, 0, 0, 0.55)");
  } else {
    // Light background → dark text.
    root.style.setProperty("--on-bg", "rgba(0, 0, 0, 0.9)");
    root.style.setProperty("--on-bg-muted", "rgba(0, 0, 0, 0.6)");
    root.style.setProperty("--on-bg-shadow", "0 1px 2px rgba(255, 255, 255, 0.4)");
  }
}

export async function applyAccentFromBackground(bg, customDataUrl = null) {
  const generation = ++accentGeneration;
  const resolvedCustomDataUrl = await customDataUrl;
  if (generation !== accentGeneration) return;

  const { dominant, lum } = await analyzeBackground(bg, resolvedCustomDataUrl);
  if (generation !== accentGeneration) return;

  lastDominant = dominant;
  lastBgLum = lum;
  applyDerivedAccent(dominant);
  applyOnBackground(lum);
}

export function applyTheme(theme) {
  const html = document.documentElement;
  if (theme === "light") {
    html.dataset.theme = "light";
  } else if (theme === "dark") {
    html.dataset.theme = "dark";
  } else {
    delete html.dataset.theme;
  }
  // Both the accent solver and the on-background text depend on the theme
  // (surface + the "none" background follow it) — re-run them on switch.
  applyDerivedAccent(lastDominant);
  applyOnBackground(lastBgLum);
}

export function applyBackground(bg, customDataUrl = null) {
  const root = document.documentElement;
  root.style.removeProperty("--bg");
  if (!bg || bg.type === "none") {
    root.style.removeProperty("--bg-image");
  } else if (bg.type === "solid") {
    root.style.removeProperty("--bg-image");
    root.style.setProperty("--bg", bg.value);
  } else if (bg.type === "gradient") {
    root.style.setProperty("--bg-image", bg.value);
  } else if (bg.type === "photo") {
    root.style.setProperty("--bg-image", `url("${bg.value}")`);
  } else if (bg.type === "custom") {
    if (customDataUrl) {
      root.style.setProperty("--bg-image", `url("${customDataUrl}")`);
    } else {
      root.style.removeProperty("--bg-image");
    }
  }
}

