  color: var(--accent);
}

/* Scope + settings icons live inside the pill, flat and inline. */
.search-container #top-actions {
  display: flex;
  align-items: center;
  gap: 2px;
  flex-shrink: 0;
}

.search-container .scope-chip,
.search-container #settings-btn {
