  background: transparent;
  box-shadow: none;
  color: var(--text-secondary);
}

.search-container .scope-chip:hover,
.search-container #settings-btn:hover {
  background: var(--surface-hover);
  color: var(--text-primary);
}

.search-container .scope-chip.active,
.search-container #settings-btn.active {
  background: color-mix(in srgb, var(--accent) 15%, transparent);
  color: var(--accent);
}

.search-container .top-actions-divider {
