  opacity: 0.85;
  /* Smaller than the title, so centering floats it high — drop it onto the
     title's baseline. */
  transform: translateY(1px);
}

.lane-delete-btn {
  background: transparent;
  border: none;
  cursor: pointer;
  color: var(--on-bg-muted, var(--text-secondary));
  text-shadow: var(--on-bg-shadow, none);
  font-size: 16px;
  line-height: 1;
  padding: 0 2px;
  margin-left: auto;
  opacity: 0;
  transition:
    opacity var(--transition),
    color var(--transition);
}

.workspace-lane:hover .lane-delete-btn {
  opacity: 1;
}

.lane-delete-btn:hover {
  color: var(--on-bg, var(--text-primary));
}

.tab-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 10px;
  padding: 8px;
  border-radius: var(--radius);
}

/* ---- Tab cards ---- */

.tab-card {
  background: var(--card-bg);
  -webkit-backdrop-filter: blur(var(--card-blur));
  backdrop-filter: blur(var(--card-blur));
  border-radius: var(--radius);
  box-shadow: var(--card-shadow);
  cursor: pointer;
  position: relative;
  overflow: hidden;
  height: 150px;
  display: flex;
  flex-direction: column;
  transition:
    transform var(--transition),
    box-shadow var(--transition);
  -webkit-user-select: none;
  user-select: none;
}

.tab-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--card-shadow-hover);
}

.tab-card:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

.card-thumbnail {
  width: 100%;
  flex: 1;
  min-height: 0;
  object-fit: cover;
  object-position: top;
  display: block;
  background: var(--surface-hover);
}

.card-thumbnail-placeholder {
  width: 100%;
  flex: 1;
  min-height: 0;
  background: var(--surface-hover);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-secondary);
  font-size: 24px;
  font-weight: 600;
  opacity: 0.4;
}

.card-info {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 0 10px;
  height: 34px;
  flex-shrink: 0;
}

.card-favicon {
  width: 14px;
  height: 14px;
  flex-shrink: 0;
}

.card-title {
  font-size: 12px;
  font-weight: 500;
  color: var(--text-primary);
  line-height: 1.4;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.card-close-btn {
  position: absolute;
  top: 5px;
  right: 5px;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.5);
  color: #fff;
  border: none;
  cursor: pointer;
  font-size: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition:
    opacity var(--transition),
    background var(--transition);
  line-height: 1;
  padding: 0;
}

.tab-card:hover .card-close-btn,
.tab-card:focus-within .card-close-btn {
  opacity: 1;
}

.card-close-btn:hover {
  background: rgba(0, 0, 0, 0.75);
}

/* ---- Settings ---- */

/* Shared dropdown shell — the bookmarks/history scope view, the
   search-everything results, and settings all render into one of these.
   Anchored beneath the search pill, borderless, separated by shadow alone
   just like the pill itself. */
.search-popup {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  right: 0;
  max-height: min(560px, calc(100vh - 120px));
  overflow: hidden auto;
  background: var(--surface);
  border-radius: var(--radius);
  box-shadow: var(--card-shadow-hover);
  z-index: 100;
}

.search-popup.hidden {
  display: none;
}

/* ---- Browser search results ---- */

#browser-search-results {
  padding: 16px 20px 24px;
}

.search-results-section {
  margin-bottom: 16px;
}

.search-results-section:last-child {
  margin-bottom: 0;
}

.search-results-label {
  padding: 8px 0 4px;
  margin-bottom: 4px;
  border-bottom: 1px solid var(--border);
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.result-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background var(--transition);
}

.result-row:hover,
.result-row:focus,
.result-row.search-selection-active {
  background: var(--surface-hover);
  outline: none;
}

.result-favicon {
  width: 16px;
  height: 16px;
  border-radius: 2px;
  flex-shrink: 0;
}

.result-favicon.load-failed {
  visibility: hidden;
}

.result-body {
  flex: 1;
  min-width: 0;
}

.result-title,
.result-meta,
.result-context {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.result-title {
  color: var(--text-primary);
  font-size: 14px;
  font-weight: 500;
}

.result-meta {
  margin-top: 1px;
  color: var(--text-secondary);
  font-size: 12px;
}

.result-context {
  max-width: 140px;
  color: var(--text-secondary);
  flex-shrink: 0;
  font-size: 12px;
  text-align: right;
}

.search-results-empty {
  padding: 16px 0;
  color: var(--text-secondary);
  font-size: 14px;
  text-align: center;
}

.search-clear-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  padding: 0;
  border: none;
  border-radius: 50%;
  background: none;
  color: var(--text-secondary);
  cursor: pointer;
  flex-shrink: 0;
  font-size: 20px;
  line-height: 1;
  transition:
    background var(--transition),
    color var(--transition);
}

.search-clear-btn:hover {
  background: var(--surface-hover);
  color: var(--text-primary);
}

.search-clear-btn.hidden {
  display: none;
}

.search-web-go {
  width: 100%;
  border: none;
  background: none;
  color: inherit;
  font: inherit;
  text-align: left;
}

.search-web-go .result-body {
  display: flex;
  flex-direction: column;
}

.bookmarks-panel-header {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 10px 12px;
  border-bottom: 1px solid var(--border);
}

.bookmarks-tabs {
  display: flex;
  gap: 4px;
}

.bookmarks-tab {
  flex: 1;
  border: none;
  background: none;
  color: var(--text-secondary);
  cursor: pointer;
  font: inherit;
  padding: 6px 10px;
  border-radius: var(--radius-sm);
}

.bookmarks-tab:hover {
  background: var(--surface-hover);
}

.bookmarks-tab.active {
  background: var(--surface-hover);
  color: var(--text-primary);
  font-weight: 600;
}

.bookmarks-subnav {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 2px;
}

.bookmarks-subnav-title {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bookmarks-open-group {
  flex: 0 0 auto;
  margin-left: auto;
  border: none;
  border-radius: var(--radius-sm);
  background: none;
  color: var(--accent);
  cursor: pointer;
  font: inherit;
  font-weight: 600;
  padding: 5px 8px;
}

.bookmarks-open-group:hover,
.bookmarks-open-group:focus-visible {
  background: var(--surface-hover);
  outline: none;
}

.bookmarks-open-group:disabled {
  color: var(--text-secondary);
  cursor: default;
  opacity: 0.6;
}

.bookmarks-open-group:disabled:hover {
  background: none;
}

.bookmarks-list {
  max-height: min(464px, calc(100vh - 132px));
  overflow-y: auto;
  padding: 6px;
}

.bookmark-row {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 10px;
  border: none;
  border-radius: var(--radius-sm);
  background: none;
  color: var(--text-primary);
  cursor: pointer;
  font: inherit;
  text-align: left;
}

.bookmark-row:hover,
.bookmark-row:focus-visible,
.bookmark-row.search-selection-active {
  background: var(--surface-hover);
  outline: none;
}

.bookmark-row span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bookmark-favicon {
  width: 16px;
  height: 16px;
  flex: 0 0 auto;
}

.bookmark-folder-icon {
  width: 16px;
  height: 16px;
  flex: 0 0 auto;
  color: var(--text-secondary);
}

.bookmark-folder-chevron {
  margin-left: auto;
  color: var(--text-secondary);
  flex: 0 0 auto;
}

.bookmarks-back {
  border: none;
  background: none;
  color: var(--accent);
  cursor: pointer;
  font: inherit;
  padding: 0;
}

.bookmarks-empty {
  margin: 0;
  padding: 24px 16px;
  color: var(--text-secondary);
  text-align: center;
}

#settings-btn {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: none;
  background: var(--surface);
  box-shadow: var(--card-shadow);
  cursor: pointer;
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 50;
  transition:
    background var(--transition),
    color var(--transition);
}

#settings-btn:hover {
  background: var(--surface-hover);
  color: var(--text-primary);
}

/* Settings is now one of the shared .search-popup dropdowns; only its own
   inner padding and scrollbar styling remain here. */
#settings-panel {
  padding: 24px;
  scrollbar-width: none;
}

#settings-panel::-webkit-scrollbar {
  width: 0;
  height: 0;
  display: none;
}

.settings-section {
  margin-top: 28px;
}

.settings-section:first-of-type {
  margin-top: 8px;
}

/* Section heading outranks the per-group .settings-label (small uppercase):
   larger, mixed-case, with a divider rule for clear two-level hierarchy. */
.settings-section-title {
  margin: 0 0 14px;
  padding-bottom: 8px;
  font-size: 15px;
  font-weight: 600;
  color: var(--text-primary);
  border-bottom: 1px solid var(--border);
}

.settings-group {
  margin-bottom: 20px;
}

.settings-label {
  display: block;
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
  margin-bottom: 8px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.settings-homepage-input {
  display: block;
  width: 100%;
  margin-top: 6px;
  padding: 7px 10px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg);
  color: var(--text-primary);
  font-size: 13px;
  font-family: inherit;
  outline: none;
  transition: border-color var(--transition);
}

.settings-homepage-input:focus {
  border-color: var(--accent);
}

.settings-homepage-input[aria-invalid="true"] {
  border-color: #dc2626;
}

.settings-homepage-feedback {
  min-height: 16px;
  margin: 4px 2px 0;
  color: #dc2626;
  font-size: 12px;
}

/* ---- Settings toggle ---- */

.settings-toggle-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  font-size: 14px;
  color: var(--text-primary);
  -webkit-user-select: none;
  user-select: none;
}

.settings-toggle-row:hover {
  background: var(--surface-hover);
}

.settings-toggle {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  cursor: pointer;
  accent-color: var(--accent);
}

.settings-permission-status {
  margin: 4px 12px 0;
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.35;
}

.settings-permission-status:empty {
  display: none;
}

/* ---- Settings privacy disclosure ---- */

.settings-privacy-summary {
  position: relative;
  margin: 0;
  padding: 0 26px 8px 0;
  color: var(--text-primary);
  border-bottom: 1px solid var(--border);
  cursor: pointer;
  font-size: 15px;
  font-weight: 600;
  list-style: none;
}

.settings-privacy-summary::-webkit-details-marker {
  display: none;
}

.settings-privacy-summary::after {
  position: absolute;
  top: 0;
  right: 4px;
  content: "›";
  color: var(--text-secondary);
  font-size: 20px;
  line-height: 1;
  transform: rotate(0deg);
  transition: transform 0.15s ease;
}

.settings-privacy-section[open] > .settings-privacy-summary::after {
  transform: rotate(90deg);
}

.settings-privacy-summary:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: 2px;
}

.settings-privacy-group {
  margin: 14px 0 0;
}

.settings-privacy-text {
  margin: 0 0 10px;
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.5;
}

.settings-privacy-text:last-of-type {
  margin-bottom: 12px;
}

.settings-privacy-link {
  display: inline-block;
  color: var(--accent);
  font-size: 13px;
  font-weight: 600;
  text-decoration: underline;
}

.settings-privacy-link:hover {
  text-decoration: none;
}

.settings-privacy-link:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 2px;
}

/* ---- Settings action button ---- */

.settings-action-btn {
  width: 100%;
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  border: 1px solid transparent;
  background: var(--bg);
  color: var(--text-primary);
  font-size: 14px;
  font-family: inherit;
  cursor: pointer;
  text-align: left;
  transition:
    background var(--transition),
    color var(--transition);
}

.settings-action-btn:hover:not(:disabled) {
  background: var(--surface-hover);
}

.settings-action-btn:disabled {
  color: var(--text-secondary);
  cursor: default;
}

/* ---- Settings Emberstone Studio footer ----
   Deliberately quieter than a real settings section: a muted eyebrow label
   (same small-caps treatment as .settings-label) instead of a bordered h3,
   and a tighter top margin, so this credit/support footer reads as its own
   named-but-subordinate group rather than an unlabeled orphan floating
   between Tabs and Privacy & Data. */

.settings-emberstone {
  margin-top: 20px;
}

.settings-emberstone-links {
  display: flex;
  flex-direction: row;
  gap: 8px;
  width: 100%;
}

.settings-emberstone-icon {
  width: 22px;
  height: 22px;
  object-fit: contain;
}

.settings-emberstone-icon.load-failed {
  visibility: hidden;
}

/* Icon-above-label card, matching the .settings-theme-btn /
   .settings-provider-card idiom used for Theme and Search Engine above —
   same column layout, sizing, and transparent-at-rest border, so these
   read as the same family of control rather than a one-off button style. */
.settings-emberstone-link {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  padding: 9px 6px;
  border-radius: var(--radius-sm);
  border: 1px solid transparent;
  background: var(--bg);
  color: var(--text-secondary);
  font-size: 11px;
  line-height: 1.2;
  text-align: center;
  text-decoration: none;
  transition:
    background var(--transition),
    color var(--transition);
}

.settings-emberstone-link:hover {
  background: var(--surface-hover);
}

.settings-emberstone-link:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

/* ---- Drag and drop ---- */

.tab-card.dragging {
  opacity: 0.5;
}

.drag-placeholder {
  min-height: 150px;
  border-radius: var(--radius);
  border: 2px dashed var(--accent);
  background: color-mix(in srgb, var(--accent) 8%, transparent);
}

.workspace-lane.drag-over .tab-grid {
  outline: 2px dashed var(--accent);
  outline-offset: 2px;
}

#new-group-drop-zone {
  margin: 0 24px 40px;
  padding: 20px;
  border: 2px dashed var(--border);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-secondary);
  font-size: 13px;
  transition:
    border-color var(--transition),
    background var(--transition),
    color var(--transition);
}

#new-group-drop-zone.drag-over {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 8%, transparent);
  color: var(--accent);
}

/* ---- Context menu ---- */

.context-menu {
  position: fixed;
  top: var(--context-menu-top, 0);
  left: var(--context-menu-left, 0);
  background: var(--surface);
  border-radius: var(--radius);
  box-shadow: var(--card-shadow-hover);
  z-index: 300;
  min-width: 180px;
  padding: 4px 0;
}

.context-menu-item {
  display: block;
  width: 100%;
  padding: 8px 14px;
  background: transparent;
  border: none;
  color: var(--text-primary);
  font-size: 13px;
  font-family: inherit;
  text-align: left;
  cursor: pointer;
  transition: background var(--transition);
}

.context-menu-item:hover {
  background: var(--surface-hover);
}

.context-menu-separator {
  height: 1px;
  background: var(--border);
  margin: 4px 0;
}

/* ---- Favicon placeholder ---- */

.favicon-placeholder {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--favicon-size, 16px);
  height: var(--favicon-size, 16px);
  border-radius: 3px;
  background: var(--accent);
  color: #fff;
  font-weight: 700;
  flex-shrink: 0;
  font-size: var(--favicon-font-size, 10px);
  line-height: 1;
}

/* ---- Utilities ---- */

.hidden {
  display: none !important;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

/* ---- Tab lightbox ---- */

#tab-lightbox {
  position: fixed;
  top: var(--lightbox-top, 0);
  left: var(--lightbox-left, 0);
  z-index: 400;
  width: 400px;
  border-radius: 6px;
  overflow: hidden;
  box-shadow: var(--card-shadow-hover);
  cursor: pointer;
  transform-origin:
    var(--lightbox-origin-x, 50%) var(--lightbox-origin-y, 50%);
  animation: lightbox-appear 200ms cubic-bezier(0.2, 0, 0.2, 1) forwards;
}

@keyframes lightbox-appear {
  from {
    transform: scale(0.64);
    opacity: 0;
  }
  to {
    transform: scale(1);
    opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  #tab-lightbox {
    animation: none;
  }
}

.lightbox-media {
  position: relative;
  width: 100%;
}

.lightbox-thumbnail {
  width: 100%;
  aspect-ratio: 16 / 10;
  object-fit: cover;
  object-position: top;
  display: block;
  background: var(--surface-hover);
}

.lightbox-placeholder {
  width: 100%;
  aspect-ratio: 16 / 10;
  background: var(--surface-hover);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 56px;
  font-weight: 700;
  color: var(--text-secondary);
}

.lightbox-body {
  background: var(--surface);
  padding: 10px 14px 12px;
}

.lightbox-title {
  margin: 0 0 6px;
  font-size: 14px;
  font-weight: 700;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1.3;
}

.lightbox-meta {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.lightbox-favicon {
  width: 14px;
  height: 14px;
  flex-shrink: 0;
}

.lightbox-url {
  font-size: 11px;
  color: var(--text-secondary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  flex: 1;
}

/* ---- Settings: theme + background ---- */

.settings-theme-row {
  display: flex;
  gap: 6px;
}

.settings-theme-btn {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  padding: 9px 6px;
  border-radius: var(--radius-sm);
  border: 1px solid transparent;
  background: var(--bg);
  color: var(--text-secondary);
  font-size: 11px;
  line-height: 1.2;
  font-family: inherit;
  cursor: pointer;
  text-align: center;
  transition:
    background var(--transition),
    border-color var(--transition),
    color var(--transition);
}

.settings-theme-icon {
  display: flex;
}

.settings-theme-icon svg {
  display: block;
}

.settings-theme-btn:hover {
  background: var(--surface-hover);
}

.settings-theme-btn.selected {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 12%, transparent);
  color: var(--accent);
  font-weight: 600;
}

/* Behavior card grid (New Tab Behavior) + provider grid (Search Engine).
   Selectable tiles that replace the native <select>s — same accent-selected
   language as the theme buttons. */
.settings-behavior-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.settings-behavior-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 12px 8px 10px;
  border-radius: var(--radius-sm);
  border: 1px solid transparent;
  background: var(--bg);
  color: var(--text-secondary);
  font-family: inherit;
  cursor: pointer;
  text-align: center;
  transition:
    background var(--transition),
    border-color var(--transition),
    color var(--transition);
}

.settings-behavior-card:hover {
  background: var(--surface-hover);
}

.settings-behavior-card.selected {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 12%, transparent);
  color: var(--accent);
}

.settings-behavior-card:focus-visible {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 25%, transparent);
}

.settings-behavior-diagram {
  display: block;
  width: 100%;
  /* Frame stays a steady muted gray on every card (selected or not) so the
     accent element inside always reads as "the behavior." */
  color: var(--text-secondary);
}

.settings-behavior-diagram svg {
  display: block;
  width: 100%;
  height: auto;
}

.settings-behavior-caption {
  font-size: 11px;
  line-height: 1.3;
}

/* Provider grid — smaller tiles, favicon over name. */
.settings-provider-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
}

.settings-provider-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 10px 4px;
  border-radius: var(--radius-sm);
  border: 1px solid transparent;
  background: var(--bg);
  color: var(--text-secondary);
  font-family: inherit;
  cursor: pointer;
  transition:
    background var(--transition),
    border-color var(--transition),
    color var(--transition);
}

.settings-provider-card:hover {
  background: var(--surface-hover);
}

.settings-provider-card.selected {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 12%, transparent);
  color: var(--accent);
  font-weight: 600;
}

.settings-provider-card:focus-visible {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 25%, transparent);
}

.settings-provider-icon {
  width: 22px;
  height: 22px;
  border-radius: 5px;
  object-fit: contain;
}

.settings-provider-icon.load-failed {
  visibility: hidden;
}

.settings-provider-name {
  font-size: 11px;
  line-height: 1.2;
}

.settings-bg-combined-grid,
.settings-bg-photo-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
  margin-top: 4px;
}

.settings-bg-swatch {
  background: var(--swatch-background, transparent);
  aspect-ratio: 16 / 10;
  border-radius: var(--radius-sm);
  border: none;
  cursor: pointer;
  overflow: hidden;
  transition:
    box-shadow var(--transition),
    transform var(--transition);
  background-size: cover;
  background-position: center;
  padding: 0;
}

.settings-bg-swatch.load-failed {
  background: var(--surface-hover);
}

.settings-bg-swatch:hover {
  transform: scale(1.05);
}

.settings-bg-swatch.selected {
  box-shadow: 0 0 0 2px var(--accent);
}

.settings-bg-swatch img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  pointer-events: none;
}

/* "None" swatch — diagonal stripes to indicate no background */
.settings-bg-swatch--none {
  background: repeating-linear-gradient(
    45deg,
    var(--surface-hover),
    var(--surface-hover) 3px,
    var(--bg) 3px,
    var(--bg) 9px
  );
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  color: var(--text-secondary);
}

.settings-bg-swatch--none:hover {
  color: var(--text-primary);
}

.settings-bg-sublabel-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 10px;
  margin-bottom: 4px;
}

.settings-bg-sublabel {
  font-size: 11px;
  color: var(--text-secondary);
  font-weight: 500;
}

.settings-bg-refresh {
  background: transparent;
  border: none;
  cursor: pointer;
  color: var(--accent);
  font-size: 12px;
  font-family: inherit;
  padding: 2px 4px;
  border-radius: var(--radius-sm);
  transition: background var(--transition);
}

.settings-bg-refresh:hover {
  background: var(--surface-hover);
}

/* Custom image tile — the first slot of the photo grid. Shares the swatch
   footprint (aspect-ratio, radius) so it reads as one of the tiles. */
.settings-bg-custom {
  position: relative;
  padding: 0;
}

/* Empty state: a blank --bg tile with a dashed border to signal "drop here". */
.settings-bg-custom--empty {
  background: var(--bg);
  border: 1px dashed var(--border);
  transition:
    border-color var(--transition),
    background var(--transition);
}

.settings-bg-custom--empty:hover {
  border-color: var(--accent);
}

.settings-bg-custom.drag-over {
  border-style: solid;
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 14%, var(--bg));
}

.settings-bg-custom.upload-error {
  border-style: solid;
  border-color: #ef4444;
}

/* The add button fills the tile; the "+" matches the new-tab buttons' glyph. */
.settings-bg-custom-add {
  width: 100%;
  height: 100%;
  border: none;
  background: transparent;
  color: var(--text-secondary);
  font-size: 22px;
  line-height: 1;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  transition: color var(--transition);
}

.settings-bg-custom--empty:hover .settings-bg-custom-add {
  color: var(--accent);
}

/* Filled state: the uploaded image's thumbnail fills the tile. */
.settings-bg-custom--filled {
  cursor: pointer;
}

.settings-bg-custom--filled img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  pointer-events: none;
}

/* Remove control — a "+" rotated 45° into an "X". Hidden until the tile is
   hovered or the button itself has keyboard focus. */
.settings-bg-custom-remove {
  position: absolute;
  inset: 0;
  border: none;
  margin: 0;
  padding: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 26px;
  line-height: 1;
  color: #fff;
  cursor: pointer;
  background: color-mix(in srgb, #000 45%, transparent);
  opacity: 0;
  transition: opacity var(--transition);
}

.settings-bg-custom-remove::before {
  content: "+";
  display: block;
  transform: rotate(45deg);
}

.settings-bg-custom--filled:hover .settings-bg-custom-remove,
.settings-bg-custom-remove:focus-visible {
  opacity: 1;
}

.settings-bg-file-input {
  display: none;
}

/* Photo-only modifiers, at the bottom of the Background section. Flush with
   the rest of the section's swatch grids and dropzone — no box/indent, since
   the "Transparency"/"Blur" labels already carry the sublabel styling that
   ties them to this section. Only rendered while a photo/custom background
   is active. */
.settings-bg-photo-adjust {
  margin-top: 12px;
}

.settings-slider-field {
  margin-bottom: 14px;
}

.settings-slider-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 6px;
}

.settings-slider-label {
  font-size: 11px;
  font-weight: 500;
  color: var(--text-secondary);
}

.settings-slider-value {
  font-size: 12px;
  color: var(--text-secondary);
  font-variant-numeric: tabular-nums;
}

.settings-slider {
  display: block;
  width: 100%;
  margin: 0;
  accent-color: var(--accent);
  cursor: pointer;
}

.settings-bg-photo-adjust .settings-toggle-row {
  padding: 6px 4px;
  font-size: 13px;
  border-radius: var(--radius-sm);
}

